<script setup>
import { computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useEvents } from '@/composables/useEvents'
const route=useRoute(),router=useRouter(),{getEventById,isUserRegistered,userRegistrations}=useEvents()
const event=computed(()=>getEventById(route.params.id))
const registration=computed(()=>userRegistrations.value.find(item=>Number(item.eventId)===Number(route.params.id)))
const status=computed(()=>!event.value?'missing':event.value.done?'closed':registration.value?'registered':event.value.seatsLeft<=0?'soldout':'available')
function date(value){if(!value)return 'Date to be announced';const d=new Date(value);return Number.isNaN(d.getTime())?value:new Intl.DateTimeFormat('en',{dateStyle:'full',timeStyle:'short'}).format(d)}
function register(){if(status.value==='available')router.push(`/browse/events/${event.value.id}/register`)}
</script>
<template><main class="detail-page"><button class="back-link" @click="router.push('/browse/events')">← Back to events</button><section v-if="event" class="detail-shell"><div class="detail-banner"><span class="orbit a"></span><span class="orbit b"></span><span class="category-tag">{{event.category}}</span><span class="banner-letter">{{event.category?.slice(0,1)||'G'}}</span></div><div class="detail-content"><article class="description"><span class="eyebrow">GATHER TOGETHER</span><h1>{{event.title}}</h1><div class="info-list"><div><small>DATE &amp; TIME</small><strong>{{date(event.date)}}</strong></div><div><small>LOCATION</small><strong>{{event.location}}</strong></div><div><small>CATEGORY</small><strong>{{event.category}}</strong></div></div><h2>About this event</h2><p>{{event.desc}}</p><p class="availability">{{event.seatsLeft}} of {{event.capacity}} spots remaining</p></article><aside class="ticket-card"><span class="eyebrow">YOUR SPOT AWAITS</span><h2>Join the experience</h2><p class="price">{{event.price||'Free'}}</p><p class="ticket-copy">{{status==='closed'?'This event has ended and registration is closed.':status==='registered'?'Your place is already reserved.':status==='soldout'?'All available spots have been reserved.':'Register now to save your place and receive your ticket.'}}</p><button v-if="status==='available'" class="register-button" @click="register">Register now →</button><button v-else-if="status==='closed'" class="register-button" disabled>Registration closed</button><button v-else-if="status==='registered'" class="register-button" disabled>Already registered ✓</button><button v-else class="register-button" disabled>Sold out</button><RouterLink v-if="status==='registered'&&registration" class="ticket-link" :to="`/your-events/${registration.id}`">View your ticket →</RouterLink><span class="ticket-note">{{status==='available'?'Your details are saved securely with your registration.':'Event information and tickets are available in Your Events.'}}</span></aside></div></section><section v-else class="not-found"><span class="not-found-icon">!</span><h1>We couldn't find that event</h1><p>It may have been removed, or the link could be out of date.</p><RouterLink to="/browse/events" class="back-button">Explore all events</RouterLink></section></main></template>
<style scoped>.detail-page{color:#211d47}.back-link{margin-bottom:1rem;padding:.4rem 0;border:0;color:#77768a;background:transparent;font-size:.82rem;font-weight:700;cursor:pointer}.detail-shell{overflow:hidden;border:1px solid #eeedf4;border-radius:22px;background:#fff;box-shadow:0 10px 36px #251d470a}.detail-banner{position:relative;display:grid;place-items:center;height:210px;overflow:hidden;background:linear-gradient(120deg,#d9d2ff,#f7e6ef 55%,#ffe0c5)}.orbit{position:absolute;border:1px solid #fff9;border-radius:50%}.orbit.a{width:280px;height:280px;left:7%;top:90px}.orbit.b{width:210px;height:210px;right:9%;top:-80px}.banner-letter{display:grid;place-items:center;width:84px;height:84px;border:1px solid #ffffffb8;border-radius:28px;color:white;background:#6748edaa;font-size:2.5rem;font-weight:800}.category-tag{position:absolute;left:1.2rem;bottom:1.1rem;padding:.4rem .65rem;border-radius:99px;color:#513ca3;background:#ffffffc9;font-size:.72rem;font-weight:750}.detail-content{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:2rem;padding:clamp(1.2rem,4vw,2.5rem)}.eyebrow{color:#9997aa;font-size:.65rem;font-weight:800;letter-spacing:.15em}.description h1{margin:.4rem 0 1.1rem;font-size:clamp(1.8rem,4vw,2.5rem);letter-spacing:-.05em}.info-list{display:grid;gap:.85rem;padding:1rem 0 1.5rem;border-bottom:1px solid #f0eff5}.info-list div{display:grid;gap:.3rem}.info-list small{color:#9997aa;font-size:.62rem;font-weight:800;letter-spacing:.1em}.info-list strong{font-size:.82rem}.description h2{margin:1.4rem 0 .5rem;font-size:1rem}.description>p{color:#77768a;font-size:.84rem;line-height:1.7}.availability{font-weight:750}.ticket-card{align-self:start;padding:1.25rem;border:1px solid #eeedf4;border-radius:16px;background:#fcfbff}.ticket-card h2{margin:.4rem 0;font-size:1.05rem}.price{margin:.9rem 0;color:#6748ed;font-size:1.2rem;font-weight:800}.ticket-copy,.ticket-note{display:block;color:#858397;font-size:.76rem;line-height:1.6}.register-button{width:100%;min-height:45px;margin:1rem 0 .7rem;border:0;border-radius:11px;color:#fff;background:#6748ed;font-size:.78rem;font-weight:750;cursor:pointer}.register-button:disabled{color:#77768a;background:#edecf2;cursor:not-allowed}.ticket-link{display:block;margin:.2rem 0 .8rem;color:#6748ed;text-align:center;text-decoration:none;font-size:.76rem;font-weight:750}.not-found{display:grid;justify-items:center;padding:4rem 1rem;text-align:center}.not-found-icon{display:grid;place-items:center;width:48px;height:48px;border-radius:16px;color:#6748ed;background:#f0edff;font-weight:800}.not-found p{color:#858397;font-size:.82rem}.back-button{color:#6748ed;font-weight:750}@media(max-width:750px){.detail-content{grid-template-columns:1fr}.ticket-card{width:auto}}</style>